    duringReading: ['الاستماع الأول: من الذي لم يحترم آدم؟ وما السبب الذي ذكره؟', 'لوّن أفعال الرأي بلون وأحكام الراوي بلون آخر.', 'ضع إطارًا حول مقارنة إبليس (النار / التراب) وحول جواب الراوي «ومع ذلك…».', 'ضع خطًّا تحت ما لم يستطع إبليس أن يراه ويقبله.'],
    afterReading: ['التحدي السريع: اذكر مع كل إجابة صاحب القول.', 'التركيز اللغوي: تصنيف الأصوات (النشاط 1)، ثم الإعراب بعد «أنّ» و«إلّا» و«أفعل من» (النشاط 2)، ثم روابط الحجة (النشاط 3).', 'اكتب أربع جمل عن رأيين مختلفين في مسألة مدرسية تنتهي بموقف مبني على الدليل.'],
    lessonPlan: '0–5 تهيئة: «يعتقد أنّ» مقابل الخبر، ويذكر المتعلمون الكلمة الدالّة؛ 5–11 استماع ثم قراءة صامتة، ثم «فحص الأصوات»: يقرأ المعلم ثماني عبارات ويرفع المتعلمون بطاقة «ش» أو «ر»؛ 11–17 خريطة الحجة في ثنائيات: ادّعاء إبليس ← سببه (الأصل) ← ما لم يستطع أن يراه (علم آدم الكامل) ← «ومع ذلك» عند الراوي، مع عبارة من النص في كل خانة، ثم قراءة جهرية مضبوطة للفقرة الثانية؛ 17–21 التحدي السريع مع نسبة القول؛ 21–30 التركيز اللغوي: النشاط 1 جماعيًّا (هل يوافق الراوي؟)، والنشاطان 2–3 في ثنائيات، ثم تحليل خطأين على السبورة بكلمة إعرابية واحدة (منصوب لأنه…)؛ 30–38 استعمال: أربع جمل عن خلاف محايد (أيّ النوادي أفضل؟ أيّ طريق إلى المدرسة أقصر؟) فيها «يرى أنّ» و«لأنّ» و«أفضل من» و«ومع ذلك»؛ 38–40 بطاقة الخروج',
    discussionPoints: ['ما المعيار الذي يستخدمه إبليس ليقرّر من الأفضل؟', 'أيّ الجمل تبيّن أن الراوي لا يشاركه رأيه؟', 'بحسب الفصل، من أين لا تأتي الأفضلية والعظمة؟', 'كيف يغيّر التواضع طريقة تعاملنا مع دليل يبيّن أننا مخطئون؟'],
    interactiveTips: ['استخدم نقطة «النار والتراب» لمقارنة إبليس، ونقطة «الكبر» لحكم الراوي.', 'أعد تشغيل «قال إبليس: …» ثم «كان إبليس متكبرا» متتاليتين واسأل: صوت من هذا؟', 'لا تقبل في الإجابة «النار أفضل من التراب» من غير «كان إبليس يرى أنّ».'],
    differentiation: { strugglingLearners: 'جدول الأصوات من عمودين وإطار مشكول: «كانَ إبليسُ يَرى أنَّ ____ لأنَّ ____. ومعَ ذلكَ، يقولُ الفصلُ إنَّ ____.»', fastFinishers: 'اكتب ست جمل تنقل رأيين في مسألة محايدة، فيها «مما جعله» ومستثنى بـ«إلّا» منصوب، وتنتهي بموقف مخالف بـ«ومع ذلك».' },
