    assessmentTools: { rubric: ['ترتيب السلسلة', 'الاستمرار', 'الجزم والنصب و«بسبب/لأنّ»', 'اللوم والمسؤولية'], exitTicket: ['اكتب جملة بـ«لم» وأخرى بـ«أمره أن…» عن موقف مدرسي، واضبط آخر الفعل في كل منهما.'] },
